-- Sayings used by the optional reactions (/parole reactions).
ns.reactionIds = { death = "lk23_34", revive = "jn11_25" }

ns.sayings = {
    { id = "jn3_16", cat = "jesus",
      fr = "Car Dieu a tant aimé le monde qu'il a donné son Fils unique, afin que quiconque croit en lui ne périsse point, mais qu'il ait la vie éternelle.", frRef = "Jean 3:16",
      en = "For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.", enRef = "John 3:16" },
    { id = "mt4_4", cat = "jesus",
      fr = "L'homme ne vivra pas de pain seulement, mais de toute parole qui sort de la bouche de Dieu.", frRef = "Matthieu 4:4",
      en = "Man shall not live by bread alone, but by every word that proceedeth out of the mouth of God.", enRef = "Matthew 4:4" },
    { id = "mt5_3", cat = "jesus",
      fr = "Heureux les pauvres en esprit, car le royaume des cieux est à eux!", frRef = "Matthieu 5:3",
      en = "Blessed are the poor in spirit: for theirs is the kingdom of heaven.", enRef = "Matthew 5:3" },
    { id = "mt5_5", cat = "jesus",
      fr = "Heureux les débonnaires, car ils hériteront la terre!", frRef = "Matthieu 5:5",
      en = "Blessed are the meek: for they shall inherit the earth.", enRef = "Matthew 5:5" },
    { id = "mt5_7", cat = "jesus",
      fr = "Heureux les miséricordieux, car ils obtiendront miséricorde!", frRef = "Matthieu 5:7",
      en = "Blessed are the merciful: for they shall obtain mercy.", enRef = "Matthew 5:7" },
    { id = "mt5_8", cat = "jesus",
      fr = "Heureux ceux qui ont le coeur pur, car ils verront Dieu!", frRef = "Matthieu 5:8",
      en = "Blessed are the pure in heart: for they shall see God.", enRef = "Matthew 5:8" },
    { id = "mt5_9", cat = "jesus",
      fr = "Heureux ceux qui procurent la paix, car ils seront appelés fils de Dieu!", frRef = "Matthieu 5:9",
      en = "Blessed are the peacemakers: for they shall be called the children of God.", enRef = "Matthew 5:9" },
    { id = "mt5_14", cat = "jesus",
      fr = "Vous êtes la lumière du monde. Une ville située sur une montagne ne peut être cachée.", frRef = "Matthieu 5:14",
      en = "Ye are the light of the world. A city that is set on an hill cannot be hid.", enRef = "Matthew 5:14" },
    { id = "mt5_16", cat = "jesus",
      fr = "Que votre lumière luise ainsi devant les hommes, afin qu'ils voient vos bonnes oeuvres, et qu'ils glorifient votre Père qui est dans les cieux.", frRef = "Matthieu 5:16",
      en = "Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.", enRef = "Matthew 5:16" },
    { id = "mt5_44", cat = "jesus",
      fr = "Aimez vos ennemis, bénissez ceux qui vous maudissent, faites du bien à ceux qui vous haïssent, et priez pour ceux qui vous maltraitent et qui vous persécutent.", frRef = "Matthieu 5:44",
      en = "Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you, and persecute you.", enRef = "Matthew 5:44" },
    { id = "mt6_21", cat = "jesus",
      fr = "Car là où est ton trésor, là aussi sera ton coeur.", frRef = "Matthieu 6:21",
      en = "For where your treasure is, there will your heart be also.", enRef = "Matthew 6:21" },
    { id = "mt6_24", cat = "jesus",
      fr = "Nul ne peut servir deux maîtres. Car, ou il haïra l'un, et aimera l'autre; ou il s'attachera à l'un, et méprisera l'autre. Vous ne pouvez servir Dieu et Mamon.", frRef = "Matthieu 6:24",
      en = "No man can serve two masters: for either he will hate the one, and love the other; or else he will hold to the one, and despise the other. Ye cannot serve God and mammon.", enRef = "Matthew 6:24" },
    { id = "mt6_34", cat = "jesus",
      fr = "Ne vous inquiétez donc pas du lendemain; car le lendemain aura soin de lui-même. A chaque jour suffit sa peine.", frRef = "Matthieu 6:34",
      en = "Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof.", enRef = "Matthew 6:34" },
    { id = "mt7_1", cat = "jesus",
      fr = "Ne jugez point, afin que vous ne soyez point jugés.", frRef = "Matthieu 7:1",
      en = "Judge not, that ye be not judged.", enRef = "Matthew 7:1" },
    { id = "mt7_3", cat = "jesus",
      fr = "Pourquoi vois-tu la paille qui est dans l'oeil de ton frère, et n'aperçois-tu pas la poutre qui est dans ton oeil?", frRef = "Matthieu 7:3",
      en = "Why beholdest thou the mote that is in thy brother's eye, but considerest not the beam that is in thine own eye?", enRef = "Matthew 7:3" },
    { id = "mt7_7", cat = "jesus",
      fr = "Demandez, et l'on vous donnera; cherchez, et vous trouverez; frappez, et l'on vous ouvrira.", frRef = "Matthieu 7:7",
      en = "Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you.", enRef = "Matthew 7:7" },
    { id = "mt7_12", cat = "jesus",
      fr = "Tout ce que vous voulez que les hommes fassent pour vous, faites-le de même pour eux, car c'est la loi et les prophètes.", frRef = "Matthieu 7:12",
      en = "All things whatsoever ye would that men should do to you, do ye even so to them: for this is the law and the prophets.", enRef = "Matthew 7:12" },
    { id = "mt7_20", cat = "jesus",
      fr = "C'est donc à leurs fruits que vous les reconnaîtrez.", frRef = "Matthieu 7:20",
      en = "By their fruits ye shall know them.", enRef = "Matthew 7:20" },
    { id = "mt11_28", cat = "jesus",
      fr = "Venez à moi, vous tous qui êtes fatigués et chargés, et je vous donnerai du repos.", frRef = "Matthieu 11:28",
      en = "Come unto me, all ye that labour and are heavy laden, and I will give you rest.", enRef = "Matthew 11:28" },
    { id = "mt18_20", cat = "jesus",
      fr = "Car là où deux ou trois sont assemblés en mon nom, je suis au milieu d'eux.", frRef = "Matthieu 18:20",
      en = "For where two or three are gathered together in my name, there am I in the midst of them.", enRef = "Matthew 18:20" },
    { id = "mt19_24", cat = "jesus",
      fr = "Il est plus facile à un chameau de passer par le trou d'une aiguille qu'à un riche d'entrer dans le royaume de Dieu.", frRef = "Matthieu 19:24",
      en = "It is easier for a camel to go through the eye of a needle, than for a rich man to enter into the kingdom of God.", enRef = "Matthew 19:24" },
    { id = "mt20_16", cat = "jesus",
      fr = "Ainsi les derniers seront les premiers, et les premiers seront les derniers.", frRef = "Matthieu 20:16",
      en = "So the last shall be first, and the first last.", enRef = "Matthew 20:16" },
    { id = "mt22_39", cat = "jesus",
      fr = "Tu aimeras ton prochain comme toi-même.", frRef = "Matthieu 22:39",
      en = "Thou shalt love thy neighbour as thyself.", enRef = "Matthew 22:39" },
    { id = "mt26_41", cat = "jesus",
      fr = "L'esprit est bien disposé, mais la chair est faible.", frRef = "Matthieu 26:41",
      en = "The spirit indeed is willing, but the flesh is weak.", enRef = "Matthew 26:41" },
    { id = "mt26_52", cat = "jesus",
      fr = "Remets ton épée à sa place; car tous ceux qui prendront l'épée périront par l'épée.", frRef = "Matthieu 26:52",
      en = "Put up again thy sword into his place: for all they that take the sword shall perish with the sword.", enRef = "Matthew 26:52" },
    { id = "mt28_20", cat = "jesus",
      fr = "Je suis avec vous tous les jours, jusqu'à la fin du monde.", frRef = "Matthieu 28:20",
      en = "I am with you alway, even unto the end of the world.", enRef = "Matthew 28:20" },
    { id = "mk2_27", cat = "jesus",
      fr = "Le sabbat a été fait pour l'homme, et non l'homme pour le sabbat.", frRef = "Marc 2:27",
      en = "The sabbath was made for man, and not man for the sabbath.", enRef = "Mark 2:27" },
    { id = "mk9_23", cat = "jesus",
      fr = "Tout est possible à celui qui croit.", frRef = "Marc 9:23",
      en = "All things are possible to him that believeth.", enRef = "Mark 9:23" },
    { id = "mk12_17", cat = "jesus",
      fr = "Rendez à César ce qui est à César, et à Dieu ce qui est à Dieu.", frRef = "Marc 12:17",
      en = "Render to Caesar the things that are Caesar's, and to God the things that are God's.", enRef = "Mark 12:17" },
    { id = "lk6_37", cat = "jesus",
      fr = "Ne jugez point, et vous ne serez point jugés; ne condamnez point, et vous ne serez point condamnés; absolvez, et vous serez absous.", frRef = "Luc 6:37",
      en = "Judge not, and ye shall not be judged: condemn not, and ye shall not be condemned: forgive, and ye shall be forgiven.", enRef = "Luke 6:37" },
    { id = "lk6_38", cat = "jesus",
      fr = "Donnez, et il vous sera donné.", frRef = "Luc 6:38",
      en = "Give, and it shall be given unto you.", enRef = "Luke 6:38" },
    { id = "lk15_7", cat = "jesus",
      fr = "Il y aura plus de joie dans le ciel pour un seul pécheur qui se repent, que pour quatre-vingt-dix-neuf justes qui n'ont pas besoin de repentance.", frRef = "Luc 15:7",
      en = "Joy shall be in heaven over one sinner that repenteth, more than over ninety and nine just persons, which need no repentance.", enRef = "Luke 15:7" },
    { id = "lk23_34", cat = "jesus",
      fr = "Père, pardonne-leur, car ils ne savent ce qu'ils font.", frRef = "Luc 23:34",
      en = "Father, forgive them; for they know not what they do.", enRef = "Luke 23:34" },
    { id = "jn6_35", cat = "jesus",
      fr = "Je suis le pain de vie. Celui qui vient à moi n'aura jamais faim, et celui qui croit en moi n'aura jamais soif.", frRef = "Jean 6:35",
      en = "I am the bread of life: he that cometh to me shall never hunger; and he that believeth on me shall never thirst.", enRef = "John 6:35" },
    { id = "jn8_7", cat = "jesus",
      fr = "Que celui de vous qui est sans péché jette le premier la pierre.", frRef = "Jean 8:7",
      en = "He that is without sin among you, let him first cast a stone.", enRef = "John 8:7" },
    { id = "jn8_12", cat = "jesus",
      fr = "Je suis la lumière du monde; celui qui me suit ne marchera pas dans les ténèbres, mais il aura la lumière de la vie.", frRef = "Jean 8:12",
      en = "I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life.", enRef = "John 8:12" },
    { id = "jn8_32", cat = "jesus",
      fr = "Vous connaîtrez la vérité, et la vérité vous affranchira.", frRef = "Jean 8:32",
      en = "And ye shall know the truth, and the truth shall make you free.", enRef = "John 8:32" },
    { id = "jn10_11", cat = "jesus",
      fr = "Je suis le bon berger. Le bon berger donne sa vie pour ses brebis.", frRef = "Jean 10:11",
      en = "I am the good shepherd: the good shepherd giveth his life for the sheep.", enRef = "John 10:11" },
    { id = "jn11_25", cat = "jesus",
      fr = "Je suis la résurrection et la vie. Celui qui croit en moi vivra, quand même il serait mort.", frRef = "Jean 11:25",
      en = "I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live.", enRef = "John 11:25" },
    { id = "jn13_34", cat = "jesus",
      fr = "Je vous donne un commandement nouveau: Aimez-vous les uns les autres; comme je vous ai aimés, vous aussi, aimez-vous les uns les autres.", frRef = "Jean 13:34",
      en = "A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another.", enRef = "John 13:34" },
    { id = "jn14_6", cat = "jesus",
      fr = "Je suis le chemin, la vérité, et la vie. Nul ne vient au Père que par moi.", frRef = "Jean 14:6",
      en = "I am the way, the truth, and the life: no man cometh unto the Father, but by me.", enRef = "John 14:6" },
    { id = "jn14_27", cat = "jesus",
      fr = "Je vous laisse la paix, je vous donne ma paix. Je ne vous donne pas comme le monde donne. Que votre coeur ne se trouble point, et ne s'alarme point.", frRef = "Jean 14:27",
      en = "Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid.", enRef = "John 14:27" },
    { id = "jn15_13", cat = "jesus",
      fr = "Il n'y a pas de plus grand amour que de donner sa vie pour ses amis.", frRef = "Jean 15:13",
      en = "Greater love hath no man than this, that a man lay down his life for his friends.", enRef = "John 15:13" },
    { id = "jn16_33", cat = "jesus",
      fr = "Vous aurez des tribulations dans le monde; mais prenez courage, j'ai vaincu le monde.", frRef = "Jean 16:33",
      en = "In the world ye shall have tribulation: but be of good cheer; I have overcome the world.", enRef = "John 16:33" },
    { id = "ac20_35", cat = "jesus",
      fr = "Il y a plus de bonheur à donner qu'à recevoir.", frRef = "Actes 20:35",
      en = "It is more blessed to give than to receive.", enRef = "Acts 20:35" },
    { id = "pr3_5", cat = "proverbs",
      fr = "Confie-toi en l'Eternel de tout ton coeur, Et ne t'appuie pas sur ta sagesse.", frRef = "Proverbes 3:5",
      en = "Trust in the Lord with all thine heart; and lean not unto thine own understanding.", enRef = "Proverbs 3:5" },
    { id = "pr6_6", cat = "proverbs",
      fr = "Va vers la fourmi, paresseux; Considère ses voies, et deviens sage.", frRef = "Proverbes 6:6",
      en = "Go to the ant, thou sluggard; consider her ways, and be wise.", enRef = "Proverbs 6:6" },
    { id = "pr10_12", cat = "proverbs",
      fr = "La haine excite des querelles, Mais l'amour couvre toutes les fautes.", frRef = "Proverbes 10:12",
      en = "Hatred stirreth up strifes: but love covereth all sins.", enRef = "Proverbs 10:12" },
    { id = "pr13_20", cat = "proverbs",
      fr = "Celui qui fréquente les sages devient sage, Mais celui qui se plaît avec les insensés s'en trouve mal.", frRef = "Proverbes 13:20",
      en = "He that walketh with wise men shall be wise: but a companion of fools shall be destroyed.", enRef = "Proverbs 13:20" },
    { id = "pr15_1", cat = "proverbs",
      fr = "Une réponse douce calme la fureur, Mais une parole dure excite la colère.", frRef = "Proverbes 15:1",
      en = "A soft answer turneth away wrath: but grievous words stir up anger.", enRef = "Proverbs 15:1" },
    { id = "pr16_9", cat = "proverbs",
      fr = "Le coeur de l'homme médite sa voie, Mais c'est l'Eternel qui dirige ses pas.", frRef = "Proverbes 16:9",
      en = "A man's heart deviseth his way: but the Lord directeth his steps.", enRef = "Proverbs 16:9" },
    { id = "pr16_18", cat = "proverbs",
      fr = "L'arrogance précède la ruine, Et l'orgueil précède la chute.", frRef = "Proverbes 16:18",
      en = "Pride goeth before destruction, and an haughty spirit before a fall.", enRef = "Proverbs 16:18" },
    { id = "pr17_22", cat = "proverbs",
      fr = "Un coeur joyeux est un bon remède, Mais un esprit abattu dessèche les os.", frRef = "Proverbes 17:22",
      en = "A merry heart doeth good like a medicine: but a broken spirit drieth the bones.", enRef = "Proverbs 17:22" },
    { id = "pr18_21", cat = "proverbs",
      fr = "La mort et la vie sont au pouvoir de la langue; Quiconque l'aime en mangera les fruits.", frRef = "Proverbes 18:21",
      en = "Death and life are in the power of the tongue: and they that love it shall eat the fruit thereof.", enRef = "Proverbs 18:21" },
    { id = "pr22_6", cat = "proverbs",
      fr = "Instruis l'enfant selon la voie qu'il doit suivre; Et quand il sera vieux, il ne s'en détournera pas.", frRef = "Proverbes 22:6",
      en = "Train up a child in the way he should go: and when he is old, he will not depart from it.", enRef = "Proverbs 22:6" },
    { id = "pr24_16", cat = "proverbs",
      fr = "Car sept fois le juste tombe, et il se relève, Mais les méchants sont précipités dans le malheur.", frRef = "Proverbes 24:16",
      en = "For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.", enRef = "Proverbs 24:16" },
    { id = "pr26_11", cat = "proverbs",
      fr = "Comme un chien qui retourne à ce qu'il a vomi, Ainsi est un insensé qui revient à sa folie.", frRef = "Proverbes 26:11",
      en = "As a dog returneth to his vomit, so a fool returneth to his folly.", enRef = "Proverbs 26:11" },
    { id = "pr27_17", cat = "proverbs",
      fr = "Comme le fer aiguise le fer, Ainsi un homme excite la colère d'un homme.", frRef = "Proverbes 27:17",
      en = "Iron sharpeneth iron; so a man sharpeneth the countenance of his friend.", enRef = "Proverbs 27:17" },
    { id = "ps23_1", cat = "psalms",
      fr = "L'Eternel est mon berger: je ne manquerai de rien.", frRef = "Psaumes 23:1",
      en = "The Lord is my shepherd; I shall not want.", enRef = "Psalm 23:1" },
    { id = "ps23_4", cat = "psalms",
      fr = "Quand je marche dans la vallée de l'ombre de la mort, Je ne crains aucun mal, car tu es avec moi: Ta houlette et ton bâton me rassurent.", frRef = "Psaumes 23:4",
      en = "Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me.", enRef = "Psalm 23:4" },
    { id = "ps27_1", cat = "psalms",
      fr = "L'Eternel est ma lumière et mon salut: De qui aurais-je crainte? L'Eternel est le soutien de ma vie: De qui aurais-je peur?", frRef = "Psaumes 27:1",
      en = "The Lord is my light and my salvation; whom shall I fear? the Lord is the strength of my life; of whom shall I be afraid?", enRef = "Psalm 27:1" },
    { id = "ps30_5", cat = "psalms",
      fr = "Car sa colère dure un instant, Mais sa grâce toute la vie; Le soir arrivent les pleurs, Et le matin l'allégresse.", frRef = "Psaumes 30:5",
      en = "For his anger endureth but a moment; in his favour is life: weeping may endure for a night, but joy cometh in the morning.", enRef = "Psalm 30:5" },
    { id = "ps37_4", cat = "psalms",
      fr = "Fais de l'Eternel tes délices, Et il te donnera ce que ton coeur désire.", frRef = "Psaumes 37:4",
      en = "Delight thyself also in the Lord; and he shall give thee the desires of thine heart.", enRef = "Psalm 37:4" },
    { id = "ps46_10", cat = "psalms",
      fr = "Arrêtez, et sachez que je suis Dieu.", frRef = "Psaumes 46:10",
      en = "Be still, and know that I am God.", enRef = "Psalm 46:10" },
    { id = "ps90_12", cat = "psalms",
      fr = "Enseigne-nous à bien compter nos jours, Afin que nous appliquions notre coeur à la sagesse.", frRef = "Psaumes 90:12",
      en = "So teach us to number our days, that we may apply our hearts unto wisdom.", enRef = "Psalm 90:12" },
    { id = "ps118_24", cat = "psalms",
      fr = "C'est ici la journée que l'Eternel a faite: Qu'elle soit pour nous un sujet d'allégresse et de joie!", frRef = "Psaumes 118:24",
      en = "This is the day which the Lord hath made; we will rejoice and be glad in it.", enRef = "Psalm 118:24" },
    { id = "ps119_105", cat = "psalms",
      fr = "Ta parole est une lampe à mes pieds, Et une lumière sur mon sentier.", frRef = "Psaumes 119:105",
      en = "Thy word is a lamp unto my feet, and a light unto my path.", enRef = "Psalm 119:105" },
    { id = "ps133_1", cat = "psalms",
      fr = "Voici, oh! qu'il est agréable, qu'il est doux Pour des frères de demeurer ensemble!", frRef = "Psaumes 133:1",
      en = "Behold, how good and how pleasant it is for brethren to dwell together in unity!", enRef = "Psalm 133:1" },
    { id = "ec1_2", cat = "ecclesiastes",
      fr = "Vanité des vanités, dit l'Ecclésiaste, vanité des vanités, tout est vanité.", frRef = "Ecclésiaste 1:2",
      en = "Vanity of vanities, saith the Preacher, vanity of vanities; all is vanity.", enRef = "Ecclesiastes 1:2" },
    { id = "ec1_9", cat = "ecclesiastes",
      fr = "Il n'y a rien de nouveau sous le soleil.", frRef = "Ecclésiaste 1:9",
      en = "There is no new thing under the sun.", enRef = "Ecclesiastes 1:9" },
    { id = "ec3_1", cat = "ecclesiastes",
      fr = "Il y a un temps pour tout, un temps pour toute chose sous les cieux.", frRef = "Ecclésiaste 3:1",
      en = "To every thing there is a season, and a time to every purpose under the heaven.", enRef = "Ecclesiastes 3:1" },
    { id = "ec4_9", cat = "ecclesiastes",
      fr = "Deux valent mieux qu'un, parce qu'ils retirent un bon salaire de leur travail.", frRef = "Ecclésiaste 4:9",
      en = "Two are better than one; because they have a good reward for their labour.", enRef = "Ecclesiastes 4:9" },
    { id = "ec9_10", cat = "ecclesiastes",
      fr = "Tout ce que ta main trouve à faire avec ta force, fais-le.", frRef = "Ecclésiaste 9:10",
      en = "Whatsoever thy hand findeth to do, do it with thy might.", enRef = "Ecclesiastes 9:10" },
    { id = "ec11_1", cat = "ecclesiastes",
      fr = "Jette ton pain sur la face des eaux, car avec le temps tu le retrouveras.", frRef = "Ecclésiaste 11:1",
      en = "Cast thy bread upon the waters: for thou shalt find it after many days.", enRef = "Ecclesiastes 11:1" },
    { id = "is40_31", cat = "scripture",
      fr = "Mais ceux qui se confient en l'Eternel renouvellent leur force. Ils prennent le vol comme les aigles; Ils courent, et ne se lassent point, Ils marchent, et ne se fatiguent point.", frRef = "Ésaïe 40:31",
      en = "But they that wait upon the Lord shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.", enRef = "Isaiah 40:31" },
    { id = "rm12_21", cat = "scripture",
      fr = "Ne te laisse pas vaincre par le mal, mais surmonte le mal par le bien.", frRef = "Romains 12:21",
      en = "Be not overcome of evil, but overcome evil with good.", enRef = "Romans 12:21" },
    { id = "1co13_13", cat = "scripture",
      fr = "Maintenant donc ces trois choses demeurent: la foi, l'espérance, la charité; mais la plus grande de ces choses, c'est la charité.", frRef = "1 Corinthiens 13:13",
