-- Lookup by id, built once.
ns.sayingsById = {}
for _, entry in ipairs(ns.sayings) do
    assert(not ns.sayingsById[entry.id], "duplicate saying id: " .. entry.id)
    ns.sayingsById[entry.id] = entry
end
